        const receive = event => {
            if (event.source !== parent || event.data?.type !== 'eiu-practice-response' || event.data.requestId !== requestId || event.data.token !== token)
                return;
            cleanup();
            const response = event.data.response;
            if (response?.success)
                resolve(response);
            else
                reject(Error(response?.message || 'Unable to complete the request.'));
        };
